"""
state.py — Clean, typed representations of parsed Kaggriculture observations.

Rewritten against the official AGENTS.md / README.md shipped inside the
installed kaggle_environments package — not guessed, not reconstructed
from an agent file's comments. Every field name and shape here is a
direct match to the documented Observation Format.
"""

from dataclasses import dataclass, field
from typing import Any


@dataclass
class TileState:
    x: int
    y: int
    locked: bool = False
    kind: str | None = None  # "PLANT" | "WEED" | "COOP" | "PASTURE" | None (empty, unlocked)

    # PLANT fields
    crop: str | None = None
    planted_day: int | None = None
    watered_today: bool = False
    consecutive_unwatered: int = 0
    yield_units: int = 0
    max_lifespan_step: int = -1  # -1 = not applicable (ongoing crop, or non-plant tile)
    fertilized_until_day: int = -1  # -1 = no active fertilizer bonus

    # COOP / PASTURE fields
    animal: str | None = None
    placed_day: int | None = None
    fed_today: bool = False
    consecutive_unfed: int = 0
    cared_today: bool = False
    fertilizer_available: bool = False
    pending_care_bonus: int = 0

    def is_fertilized(self, current_day: int) -> bool:
        return self.fertilized_until_day >= current_day

    @classmethod
    def from_raw(cls, x: int, y: int, raw_cell: Any) -> "TileState":
        if raw_cell is None:
            return cls(x=x, y=y)
        if raw_cell == "LOCKED":
            return cls(x=x, y=y, locked=True)
        if not isinstance(raw_cell, dict):
            # Unrecognized shape -- treat as empty rather than crash.
            return cls(x=x, y=y)

        kind = raw_cell.get("kind")
        if kind == "PLANT":
            return cls(
                x=x, y=y, kind="PLANT",
                crop=raw_cell.get("crop"),
                planted_day=raw_cell.get("planted_day"),
                watered_today=raw_cell.get("watered_today", False),
                consecutive_unwatered=raw_cell.get("consecutive_unwatered", 0),
                yield_units=raw_cell.get("yield_units", 0),
                max_lifespan_step=raw_cell.get("max_lifespan_step", -1),
                fertilized_until_day=raw_cell.get("fertilized_until_day", -1),
            )
        if kind == "WEED":
            return cls(x=x, y=y, kind="WEED")
        if kind in ("COOP", "PASTURE"):
            return cls(
                x=x, y=y, kind=kind,
                animal=raw_cell.get("animal"),
                placed_day=raw_cell.get("placed_day"),
                yield_units=raw_cell.get("yield_units", 0),
                fed_today=raw_cell.get("fed_today", False),
                consecutive_unfed=raw_cell.get("consecutive_unfed", 0),
                cared_today=raw_cell.get("cared_today", False),
                fertilizer_available=raw_cell.get("fertilizer_available", False),
                pending_care_bonus=raw_cell.get("pending_care_bonus", 0),
            )
        return cls(x=x, y=y)  # unrecognized "kind" -- treat as empty


@dataclass
class UnitState:
    unit_id: str  # "farmer" or "hand_0", "hand_1", ... -- local bookkeeping
    # only; never sent back in the action (the real action addresses the
    # farmer and hands by their fixed "farmer"/"hands" keys, not by id).
    x: int
    y: int
    carrying: dict[str, int] = field(default_factory=dict)


@dataclass
class FarmState:
    step: int
    day: int
    hour: int
    money: float
    shed: dict[str, int]
    seeds: dict[str, int]
    market_prices: dict[str, float]
    market_inventory: dict[str, int]
    unlocked_shops: list[str]
    unlocked_quadrants: list[str]  # e.g. ["NW"] -- names, not a count
    hires_today: int
    tiles: list[TileState]
    farmer: UnitState
    hands: list[UnitState]


def size_keeper_pool(n_units: int, n_animals_active: int) -> int:
    """
    Independently verified stable-pool-sizing formula. Sizing off herd size
    rather than raw unit count keeps pool membership stable across a
    same-day hire. Kept ready for when hiring is implemented and n_units
    actually grows past 1.
    """
    return max(1, min(3, n_units - 2, 1 + n_animals_active // 3))

# -------- from strategy.py --------
"""
strategy.py — Task generation and prioritization.

Rewritten against the official tile schema (kind-discriminated: "PLANT",
"WEED", "COOP", "PASTURE", or empty). HARVEST priority is driven directly
by max_lifespan_step (decay) for one-time crops -- the single biggest gap
in every prior version of this project.

Known gaps, intentionally not solved here:
- Ongoing-crop (tomato/strawberry) decay isn't modeled: their
  max_lifespan_step is always -1 (the engine tracks their decay trigger
  by cumulative production count, not a step number), and that count
  isn't derivable from a single observation.
- Crop selection for empty tiles is a placeholder (always WHEAT).
- Only the main farmer is assigned a task; hands (once hiring is
  implemented) aren't scheduled yet.
"""

from dataclasses import dataclass



@dataclass
class Task:
    kind: str
    tile: TileState
    urgency: float  # higher = more urgent; used to sort, not a fixed tier


BASE_URGENCY: dict[str, float] = {
    "FEED_CRITICAL": 100.0,
    "WATER_CRITICAL": 95.0,
    "HARVEST_DECAYING": 90.0,
    "PLACE": 80.0,
    "FEED_ROUTINE": 60.0,
    "PLANT_ABUNDANT": 65.0,  # see generate_tasks() -- only used when empty land >= unit count
    "WATER_ROUTINE": 55.0,
    "HARVEST_FRESH": 50.0,
    "CARE": 45.0,
    "DIG": 40.0,
    "BUILD": 35.0,
    "PLANT": 30.0,
    "FERTILIZE": 20.0,
    "COLLECT_FERTILIZER": 10.0,
}


def harvest_urgency(tile: TileState, current_step: int) -> float:
    """Decay-aware HARVEST urgency for a PLANT tile. Reads
    max_lifespan_step directly rather than inferring decay."""
    urgency = decay_urgency(tile.max_lifespan_step, current_step)
    if urgency > 0:
        return BASE_URGENCY["HARVEST_DECAYING"] + min(urgency, 10.0) * max(tile.yield_units, 1)
    if tile.yield_units > 0:
        return BASE_URGENCY["HARVEST_FRESH"]
    return 0.0


def generate_tasks(farm: FarmState) -> list[Task]:
    tasks: list[Task] = []

    # If there's at least as much unclaimed empty land as there are units
    # to work it, treat expansion (PLANT) as competitive with routine
    # upkeep instead of always losing to it. Without this, a small
    # established cluster of planted tiles generates recurring
    # WATER/HARVEST obligations that permanently outrank PLANT (30 <
    # WATER_ROUTINE's 55), so every unit gets absorbed into maintaining
    # the same few tiles forever and expansion never happens. Confirmed
    # in a real run: 4 units settled onto exactly 4 tiles and never grew
    # past them -- 21 of 25 NW tiles sat untouched the whole episode.
    # PLANT_ABUNDANT still loses to anything that risks an actual loss
    # (FEED_CRITICAL/WATER_CRITICAL/HARVEST_DECAYING/PLACE) -- only
    # routine upkeep yields to it.
    n_units = 1 + len(farm.hands)
    empty_count = sum(1 for t in farm.tiles if not t.locked and t.kind is None)
    plant_urgency = BASE_URGENCY["PLANT_ABUNDANT"] if empty_count >= n_units else BASE_URGENCY["PLANT"]

    for tile in farm.tiles:
        if tile.locked:
            continue  # every tile action no-ops on an unbought quadrant

        if tile.kind == "WEED":
            tasks.append(Task("DIG", tile, BASE_URGENCY["DIG"]))
            continue

        if tile.kind == "PLANT":
            u = harvest_urgency(tile, farm.step)
            if u > 0:
                tasks.append(Task("HARVEST", tile, u))
            if not tile.watered_today:
                grace_left = MAX_CONSECUTIVE_UNWATERED - tile.consecutive_unwatered
                key = "WATER_CRITICAL" if grace_left <= 1 else "WATER_ROUTINE"
                tasks.append(Task("WATER", tile, BASE_URGENCY[key]))
            if not tile.is_fertilized(farm.day):
                tasks.append(Task("FERTILIZE", tile, BASE_URGENCY["FERTILIZE"]))
            continue

        if tile.kind in ("COOP", "PASTURE"):
            if tile.animal is None:
                tasks.append(Task("PLACE", tile, BASE_URGENCY["PLACE"]))
            else:
                if tile.yield_units > 0:
                    tasks.append(Task("HARVEST", tile, BASE_URGENCY["HARVEST_FRESH"]))
                if not tile.fed_today:
                    grace_left = MAX_CONSECUTIVE_UNFED - tile.consecutive_unfed
                    key = "FEED_CRITICAL" if grace_left <= 1 else "FEED_ROUTINE"
                    tasks.append(Task("FEED", tile, BASE_URGENCY[key]))
                if not tile.cared_today:
                    tasks.append(Task("CARE", tile, BASE_URGENCY["CARE"]))
                if tile.fertilizer_available:
                    tasks.append(Task("COLLECT_FERTILIZER", tile, BASE_URGENCY["COLLECT_FERTILIZER"]))
            continue

        # tile.kind is None -- empty, unlocked, plantable
        tasks.append(Task("PLANT", tile, plant_urgency))

    tasks.sort(key=lambda t: t.urgency, reverse=True)
    return tasks


def shop_aware_sell_plan(farm: FarmState, max_orders: int = 8) -> list[tuple[str, int]]:
    """
    Sell whatever's in the shed. Unsold inventory earns nothing (the
    confirmed reward rule: "unsold items in inventory do not count"), so
    there's no reason to hold produce back at this scale.

    This replaces an earlier version that only sold once the shed was
    nearly full -- a reasonable-sounding "don't let it overflow"
    heuristic that was actually the reason a real test run showed money
    going steadily DOWN over 720 turns: with one or two crop tiles, the
    shed never gets anywhere near full, so that version silently never
    sold anything while still spending on seeds. Matches the pattern in
    AGENTS.md's own reference agent instead (sell unconditionally, no
    threshold). mechanics.py::per_turn_shop_demand is still there for a
    later pass that times sales around passive town demand -- not used
    to gate selling for now.
    """
    plan: list[tuple[str, int]] = [(item, qty) for item, qty in farm.shed.items() if qty > 0]
    plan.sort(key=lambda p: p[1], reverse=True)
    return plan[:max_orders]

# -------- from agent.py --------
"""
agent.py — Kaggriculture submission entrypoint.

Rewritten against the official AGENTS.md / README.md shipped inside the
installed kaggle_environments package. Both the observation shape and the
action format below are direct matches to that documentation, not guesses:

    return {
        "farmer": [op, ...args],
        "hands":  [[op, ...args], ...],   # one per hired hand, in order
        "market": [[op, ...args], ...],
    }

This is the fix for the earlier version, which returned a bare list
(["WEST"]) — silently wrong, since the engine expects this dict shape.
That's almost certainly why reward stayed pinned at exactly $3000 even
once the observation parsing itself was corrected.
"""

import logging
from typing import Any


logger = logging.getLogger("kaggriculture_agent")
logging.basicConfig(level=logging.WARNING)

# Placeholder crop-selection heuristic -- always WHEAT. CROPS in
# mechanics.py has profiles for CARROT/TOMATO/STRAWBERRY/MELON too; a real
# selection heuristic (season timing, market price, land-use mix) is the
# next piece of strategy to build, not this pass.
DEFAULT_PLANT_CROP = "WHEAT"


def parse_observation(obs: dict[str, Any], config: dict[str, Any]) -> FarmState:
    player_idx = obs["player"]
    my_farm = obs["farms"][player_idx]
    private = obs["private"]
    market = obs["market"]
    town = obs["town"]

    tiles: list[TileState] = [
        TileState.from_raw(x, y, cell)
        for y, row in enumerate(my_farm["tiles"])
        for x, cell in enumerate(row)
    ]

    # private["inventories"][0] is the main farmer; [1:] are hands, in the
    # same order as farm["hands"].
    raw_inventories = private.get("inventories", [])

    fx, fy = my_farm["farmer"]
    farmer = UnitState(
        unit_id="farmer",
        x=fx,
        y=fy,
        carrying=raw_inventories[0] if raw_inventories else {},
    )

    hands: list[UnitState] = []
    for i, (hx, hy) in enumerate(my_farm.get("hands", [])):
        carrying = raw_inventories[i + 1] if i + 1 < len(raw_inventories) else {}
        hands.append(UnitState(unit_id=f"hand_{i}", x=hx, y=hy, carrying=carrying))

    return FarmState(
        step=obs.get("step", 0),
        day=obs.get("day", 0),
        hour=obs.get("hour", 0),
        money=my_farm.get("money", 0.0),
        shed=private.get("shed", {}),
        seeds=private.get("seeds", {}),
        market_prices=market.get("prices", {}),
        market_inventory=market.get("inventory", {}),
        unlocked_shops=town.get("unlocked_shops", []),
        unlocked_quadrants=my_farm.get("unlocked_quadrants", []),
        hires_today=my_farm.get("hires_today", 0),
        tiles=tiles,
        farmer=farmer,
        hands=hands,
    )


def _direction_toward(from_x: int, from_y: int, to_x: int, to_y: int) -> str | None:
    """Greedy straight-line stepping -- locked tiles are confirmed
    passable, so no pathfinding/obstacle-avoidance is needed."""
    dx = to_x - from_x
    dy = to_y - from_y
    if dx == 0 and dy == 0:
        return None
    if abs(dx) >= abs(dy):
        return "EAST" if dx > 0 else "WEST"
    return "SOUTH" if dy > 0 else "NORTH"


def _distance(ax: int, ay: int, bx: int, by: int) -> int:
    """Manhattan distance -- matches 4-directional movement exactly."""
    return abs(ax - bx) + abs(ay - by)


# Keep this much cash in reserve on top of a hire's own cost, so a HIRE
# order doesn't get queued the same turn that empties the bank for a seed
# purchase or land buy.
HIRE_MONEY_BUFFER = 50

# Hands disappear at the end of every day and must be re-hired from
# scratch (confirmed) -- and cost is fib(hires_today), resetting daily,
# so it escalates fast WITHIN a day: 1, 1, 2, 3, 5, 8, 13, 21, ... A
# "backlog exceeds units" trigger alone never stops firing early on --
# 25 empty tiles outnumbers even a dozen units -- so an early real run
# hired every single turn and the escalating fibonacci cost crashed the
# bank from 3000 to 40 in one day. Capped here instead: at most this many
# hires per day, regardless of backlog. Confirmed working and profitable
# in a real run at 3 (3934 -> 5855); still a starting guess, not tuned
# further than that one data point.
MAX_HIRES_PER_DAY = 3

# Land-buying: unlike hiring, each quadrant is a one-time purchase (no
# fibonacci-style escalation risk -- QUADRANT_COSTS is fixed, and
# unlocked_quadrants only grows), so the failure mode here is different:
# buying too early wastes money that could hire/seed instead, buying too
# late leaves units idle with nowhere left to plant. Buy once unlocked,
# empty (plantable) tiles run low relative to how much labor there is.
LAND_BUY_MIN_EMPTY_TILES = 3
LAND_BUY_MONEY_BUFFER = 500  # bigger buffer than hiring's -- land costs up to $4k


def _maybe_buy_land(farm: FarmState) -> list[Any] | None:
    if len(farm.unlocked_quadrants) >= len(QUADRANT_NAMES):
        return None  # fully unlocked already

    empty_tiles = sum(1 for t in farm.tiles if not t.locked and t.kind is None)
    if empty_tiles > LAND_BUY_MIN_EMPTY_TILES:
        return None  # still room to plant -- don't spend on land yet

    # BUY_LAND takes no arguments (confirmed) -- the engine decides which
    # quadrant unlocks. Cost is fixed by how many you already own:
    # $1k/$2k/$4k for the 2nd/3rd/4th (QUADRANT_COSTS[len(unlocked)-1]).
    cost = QUADRANT_COSTS[len(farm.unlocked_quadrants) - 1]
    if farm.money >= cost + LAND_BUY_MONEY_BUFFER:
        return ["BUY_LAND"]
    return None


def _decide_ops(farm: FarmState) -> tuple[list[Any], list[list[Any]], list[Any]]:
    """
    Repeatedly takes the highest remaining urgency level and, within that
    tied group, picks whichever (task, unit) pairing is physically
    closest -- so equal-priority tasks get resolved by distance instead
    of arbitrary list order. This matters a lot in practice: with a
    single farmer and 25 equally-urgent empty tiles, list order alone
    previously sent it walking across the whole quadrant while an
    equally urgent, zero-distance tile (the one it was already standing
    on) sat ignored. Units CAN share a tile (confirmed), so two units can
    legitimately be sent to the same tile to do two different things.

    Known limitation: this is a greedy nearest-pair heuristic, not a true
    optimal assignment (Hungarian-algorithm territory) -- good enough for
    a handful of units against a few dozen tasks.
    """
    tasks = generate_tasks(farm)  # sorted by urgency, descending
    units = [farm.farmer, *farm.hands]
    ops: dict[int, list[Any]] = {}
    remaining_task_idxs = list(range(len(tasks)))
    remaining_units = list(range(len(units)))
    market_orders: list[Any] = []
    wheat_seeds_committed = 0

    # Proactively keep at least one wheat seed in the pipeline whenever a
    # PLANT task is pending -- buying only once a unit physically arrives
    # at an empty tile would waste however many turns the walk took.
    if any(t.kind == "PLANT" for t in tasks) and farm.seeds.get(DEFAULT_PLANT_CROP, 0) <= 0:
        cost = CROPS[DEFAULT_PLANT_CROP].seed_cost
        if farm.money >= cost:
            market_orders.append(["BUY_SEED", DEFAULT_PLANT_CROP, 1])

    while remaining_task_idxs and remaining_units:
        top_urgency = tasks[remaining_task_idxs[0]].urgency
        tied = [ti for ti in remaining_task_idxs if tasks[ti].urgency == top_urgency]
        ti, ui = min(
            ((t, u) for t in tied for u in remaining_units),
            key=lambda pair: _distance(
                units[pair[1]].x, units[pair[1]].y, tasks[pair[0]].tile.x, tasks[pair[0]].tile.y
            ),
        )
        remaining_task_idxs.remove(ti)
        remaining_units.remove(ui)
        task, unit = tasks[ti], units[ui]

        direction = _direction_toward(unit.x, unit.y, task.tile.x, task.tile.y)
        if direction is not None:
            ops[ui] = [direction]
            continue

        if task.kind != "PLANT":
            ops[ui] = [task.kind]
            continue

        # Standing on an empty tile -- plant if there's seed left after
        # what's already been committed to other units this same turn.
        # Confirmed: if two units both PLANT the same turn with
        # insufficient seed for both, NEITHER plants.
        if farm.seeds.get(DEFAULT_PLANT_CROP, 0) - wheat_seeds_committed > 0:
            ops[ui] = ["PLANT", DEFAULT_PLANT_CROP]
            wheat_seeds_committed += 1
        else:
            ops[ui] = ["PASS"]  # seed queued above but hasn't landed yet

    for ui in remaining_units:
        ops[ui] = ["PASS"]  # more units than tasks this turn

    # More backlog than units to cover it, and we can afford another --
    # hire one, up to the daily cap. The new hand shows up next turn.
    if len(tasks) > len(units) and farm.hires_today < MAX_HIRES_PER_DAY:
        cost = hire_cost(farm.hires_today)
        if farm.money >= cost + HIRE_MONEY_BUFFER:
            market_orders.append(["HIRE"])

    land_order = _maybe_buy_land(farm)
    if land_order:
        market_orders.append(land_order)

    # Sell whatever fits in whatever market-order slots are left this
    # turn (utility orders above take priority; extras past
    # MAX_MARKET_ORDERS_PER_TURN are silently dropped by the engine, so
    # sizing this dynamically means a sell never crowds out a buy/hire).
    remaining_slots = max(0, MAX_MARKET_ORDERS_PER_TURN - len(market_orders))
    for item, qty in shop_aware_sell_plan(farm, max_orders=remaining_slots):
        market_orders.append(["SELL", item, qty])

    farmer_op = ops.get(0, ["PASS"])
    hand_ops = [ops.get(i, ["PASS"]) for i in range(1, len(units))]
    return farmer_op, hand_ops, market_orders


def agent(obs: dict[str, Any], config: dict[str, Any]) -> dict[str, Any]:
    try:
        farm = parse_observation(obs, config)
    except Exception:
        logger.exception("parse_observation failed; passing this turn as a safe fallback")
        return {"farmer": ["PASS"], "hands": [], "market": []}

    farmer_op, hand_ops, market_orders = _decide_ops(farm)
    return {"farmer": farmer_op, "hands": hand_ops, "market": market_orders}

